fn write_query_builder_list(output: &mut StreamOutput, queries: &[OpenSearchQueryBuilderWire]) {
    output.write_vint(queries.len() as i32);
    for query in queries {
        write_named_query_builder(output, query);
    }
}

fn read_query_builder_list(
    input: &mut StreamInput,
) -> Result<Vec<OpenSearchQueryBuilderWire>, TransportActionWireError> {
    let len = read_len(input)?;
    let mut queries = Vec::with_capacity(len);
    for _ in 0..len {
        queries.push(read_named_query_builder(input)?);
    }
    Ok(queries)
}

fn write_filter_function_list(
    output: &mut StreamOutput,
    functions: &[OpenSearchFilterFunctionBuilderWire],
) {
    output.write_vint(functions.len() as i32);
    for function in functions {
        write_named_query_builder(output, &function.filter);
        write_named_score_function_builder(output, &function.score_function);
    }
}

fn read_filter_function_list(
    input: &mut StreamInput,
) -> Result<Vec<OpenSearchFilterFunctionBuilderWire>, TransportActionWireError> {
    let len = read_len(input)?;
    let mut functions = Vec::with_capacity(len);
    for _ in 0..len {
        functions.push(OpenSearchFilterFunctionBuilderWire {
            filter: Box::new(read_named_query_builder(input)?),
            score_function: read_named_score_function_builder(input)?,
        });
    }
    Ok(functions)
}

fn write_named_score_function_builder(
    output: &mut StreamOutput,
    function: &OpenSearchScoreFunctionBuilderWire,
) {
    match function {
        OpenSearchScoreFunctionBuilderWire::Weight(function) => {
            output.write_string("weight");
            write_optional_float(output, function.weight);
            output.write_optional_string(function.function_name.as_deref());
        }
    }
}

fn read_named_score_function_builder(
    input: &mut StreamInput,
) -> Result<OpenSearchScoreFunctionBuilderWire, TransportActionWireError> {
    let name = input.read_string()?;
    match name.as_str() {
        "weight" => Ok(OpenSearchScoreFunctionBuilderWire::Weight(
            OpenSearchWeightScoreFunctionBuilderWire {
                weight: read_optional_float(input)?,
                function_name: input.read_optional_string()?,
            },
        )),
        _ => Err(TransportActionWireError::UnsupportedWireShape {
            shape: "search request source query function_score score function",
            reason: "only OpenSearch weight score functions are decoded by this subset",
        }),
    }
}

fn validate_query_builder_list(
    queries: &[OpenSearchQueryBuilderWire],
) -> Result<(), TransportActionWireError> {
    for query in queries {
        validate_query_builder(Some(query))?;
    }
    Ok(())
}

fn validate_score_function_builder(
    function: &OpenSearchScoreFunctionBuilderWire,
) -> Result<(), TransportActionWireError> {
    match function {
        OpenSearchScoreFunctionBuilderWire::Weight(function) => {
            if function
                .weight
                .is_some_and(|weight| !weight.is_finite() || weight <= 0.0)
            {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query function_score score function",
                    reason: "OpenSearch weight score function weight must be finite and positive in this execution subset",
                });
            }
            if function.function_name.as_deref().is_some_and(str::is_empty) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query function_score score function",
                    reason: "OpenSearch score function name must be non-empty when present",
                });
            }
        }
    }
    Ok(())
}

fn query_builder_is_supported_span_clause(query: &OpenSearchQueryBuilderWire) -> bool {
    match query {
        OpenSearchQueryBuilderWire::SpanTerm(_) => true,
        OpenSearchQueryBuilderWire::SpanMulti(query) => {
            matches!(query.query.as_ref(), OpenSearchQueryBuilderWire::Prefix(_))
        }
        _ => false,
    }
}

fn validate_query_builder(
    query: Option<&OpenSearchQueryBuilderWire>,
) -> Result<(), TransportActionWireError> {
    let Some(query) = query else {
        return Ok(());
    };
    match query {
        OpenSearchQueryBuilderWire::Bool(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            validate_optional_non_empty_query_string(query.minimum_should_match.as_deref())?;
            validate_query_builder_list(&query.must)?;
            validate_query_builder_list(&query.must_not)?;
            validate_query_builder_list(&query.should)?;
            validate_query_builder_list(&query.filter)?;
        }
        OpenSearchQueryBuilderWire::Boosting(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            validate_query_builder(Some(&query.positive))?;
            validate_query_builder(Some(&query.negative))?;
            if !query.negative_boost.is_finite() || query.negative_boost < 0.0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch BoostingQueryBuilder negative boost must be finite and non-negative",
                });
            }
        }
        OpenSearchQueryBuilderWire::Common(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch CommonTermsQueryBuilder field name must be non-empty",
                });
            }
            validate_match_query_value(&query.text)?;
            validate_optional_non_empty_query_string(query.analyzer.as_deref())?;
            validate_optional_non_empty_query_string(
                query.low_freq_minimum_should_match.as_deref(),
            )?;
            validate_optional_non_empty_query_string(
                query.high_freq_minimum_should_match.as_deref(),
            )?;
            if !query.cutoff_frequency.is_finite() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch CommonTermsQueryBuilder cutoff frequency must be finite",
                });
            }
        }
        OpenSearchQueryBuilderWire::CombinedFields(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if !matches!(query.query_value, Value::String(_)) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch CombinedFieldsQueryBuilder query value must be a string",
                });
            }
            if query.fields.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch CombinedFieldsQueryBuilder fields must be non-empty",
                });
            }
            for field in &query.fields {
                if field.field_name.is_empty() {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query",
                        reason:
                            "OpenSearch CombinedFieldsQueryBuilder field name must be non-empty",
                    });
                }
                if !field.weight.is_finite() {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query",
                        reason: "OpenSearch CombinedFieldsQueryBuilder field weight must be finite",
                    });
                }
            }
            validate_optional_non_empty_query_string(query.minimum_should_match.as_deref())?;
        }
        OpenSearchQueryBuilderWire::ConstantScore(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            validate_query_builder(Some(&query.filter))?;
        }
        OpenSearchQueryBuilderWire::DisMax(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            validate_query_builder_list(&query.queries)?;
            if !query.tie_breaker.is_finite() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch DisMaxQueryBuilder tie breaker must be finite",
                });
            }
        }
        OpenSearchQueryBuilderWire::Exists(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch ExistsQueryBuilder field name must be non-empty",
                });
            }
        }
        OpenSearchQueryBuilderWire::FieldMaskingSpan(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch FieldMaskingSpanQueryBuilder field name must be non-empty",
                });
            }
            if !matches!(
                query.query.as_ref(),
                OpenSearchQueryBuilderWire::SpanTerm(_)
            ) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query field_masking_span query",
                    reason: "OpenSearch FieldMaskingSpanQueryBuilder query must be span_term in this execution subset",
                });
            }
            validate_query_builder(Some(query.query.as_ref()))?;
        }
        OpenSearchQueryBuilderWire::FunctionScore(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            validate_query_builder(Some(query.query.as_ref()))?;
            if !query.max_boost.is_finite() || query.max_boost < 0.0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch FunctionScoreQueryBuilder max_boost must be finite and non-negative",
                });
            }
            if query
                .min_score
                .is_some_and(|min_score| !min_score.is_finite() || min_score < 0.0)
            {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch FunctionScoreQueryBuilder min_score must be finite and non-negative when present",
                });
            }
            if !matches!(
                query.boost_mode,
                None | Some(OpenSearchCombineFunctionWire::Multiply)
                    | Some(OpenSearchCombineFunctionWire::Replace)
            ) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch FunctionScoreQueryBuilder boost_mode must be multiply or replace in this execution subset",
                });
            }
            if query.score_mode != OpenSearchFunctionScoreModeWire::Multiply {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch FunctionScoreQueryBuilder score_mode must be multiply in this execution subset",
                });
            }
            if query.filter_functions.len() > 1 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query function_score functions",
                    reason: "only a single top-level weight function is supported by this execution subset",
                });
            }
            for function in &query.filter_functions {
                if !matches!(
                    function.filter.as_ref(),
                    OpenSearchQueryBuilderWire::MatchAll(_)
                ) {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query function_score filter",
                        reason:
                            "only match_all function filters are supported by this execution subset",
                    });
                }
                validate_score_function_builder(&function.score_function)?;
            }
        }
        OpenSearchQueryBuilderWire::Fuzzy(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch FuzzyQueryBuilder field name must be non-empty",
                });
            }
            validate_term_query_value(&query.value)?;
            validate_fuzziness(&query.fuzziness)?;
            if query.prefix_length < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch FuzzyQueryBuilder prefix length must be non-negative",
                });
            }
            if query.max_expansions <= 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch FuzzyQueryBuilder max expansions must be positive",
                });
            }
            validate_optional_non_empty_query_string(query.rewrite.as_deref())?;
        }
        OpenSearchQueryBuilderWire::GeoDistance(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch GeoDistanceQueryBuilder field name must be non-empty",
                });
            }
            if !query.distance_meters.is_finite() || query.distance_meters < 0.0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch GeoDistanceQueryBuilder distance must be finite and non-negative",
                });
            }
            if !query.center.lat.is_finite() || !query.center.lon.is_finite() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch GeoDistanceQueryBuilder center point must contain finite coordinates",
                });
            }
            if query.validation_method == OpenSearchGeoValidationMethodWire::Strict
                && !((-90.0..=90.0).contains(&query.center.lat)
                    && (-180.0..=180.0).contains(&query.center.lon))
            {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch GeoDistanceQueryBuilder strict center point must be in latitude/longitude bounds",
                });
            }
        }
        OpenSearchQueryBuilderWire::Ids(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
        }
        OpenSearchQueryBuilderWire::MatchAll(query) => {
            if !query.boost.is_finite() || query.boost < 0.0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchAllQueryBuilder boost must be finite and non-negative",
                });
            }
            if query.query_name.as_deref().is_some_and(str::is_empty) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch MatchAllQueryBuilder query name must be non-empty when present",
                });
            }
        }
        OpenSearchQueryBuilderWire::MatchNone(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
        }
        OpenSearchQueryBuilderWire::Match(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchQueryBuilder field name must be non-empty",
                });
            }
            validate_match_query_value(&query.value)?;
            if query.prefix_length < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchQueryBuilder prefix length must be non-negative",
                });
            }
            if query.max_expansions <= 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchQueryBuilder max expansions must be positive",
                });
            }
            validate_optional_non_empty_query_string(query.analyzer.as_deref())?;
            validate_optional_non_empty_query_string(query.minimum_should_match.as_deref())?;
            validate_optional_non_empty_query_string(query.fuzzy_rewrite.as_deref())?;
            if query
                .cutoff_frequency
                .is_some_and(|cutoff_frequency| !cutoff_frequency.is_finite())
            {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch MatchQueryBuilder cutoff frequency must be finite when present",
                });
            }
        }
        OpenSearchQueryBuilderWire::MatchBoolPrefix(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchBoolPrefixQueryBuilder field name must be non-empty",
                });
            }
            validate_match_query_value(&query.value)?;
            validate_optional_non_empty_query_string(query.analyzer.as_deref())?;
            validate_optional_non_empty_query_string(query.minimum_should_match.as_deref())?;
            if let Some(fuzziness) = &query.fuzziness {
                validate_fuzziness(fuzziness)?;
            }
            if query.prefix_length < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch MatchBoolPrefixQueryBuilder prefix length must be non-negative",
                });
            }
            if query.max_expansions <= 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch MatchBoolPrefixQueryBuilder max expansions must be positive",
                });
            }
            validate_optional_non_empty_query_string(query.fuzzy_rewrite.as_deref())?;
        }
        OpenSearchQueryBuilderWire::MatchPhrase(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchPhraseQueryBuilder field name must be non-empty",
                });
            }
            validate_match_query_value(&query.value)?;
            if query.slop < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchPhraseQueryBuilder slop must be non-negative",
                });
            }
            if query.zero_terms_query == OpenSearchZeroTermsQueryWire::Null {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch MatchPhraseQueryBuilder zero terms query must be NONE or ALL",
                });
            }
            validate_optional_non_empty_query_string(query.analyzer.as_deref())?;
        }
        OpenSearchQueryBuilderWire::MatchPhrasePrefix(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchPhrasePrefixQueryBuilder field name must be non-empty",
                });
            }
            validate_match_query_value(&query.value)?;
            if query.slop < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchPhrasePrefixQueryBuilder slop must be non-negative",
                });
            }
            if query.max_expansions < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchPhrasePrefixQueryBuilder max expansions must be non-negative",
                });
            }
            if query.zero_terms_query == OpenSearchZeroTermsQueryWire::Null {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MatchPhrasePrefixQueryBuilder zero terms query must be NONE or ALL",
                });
            }
            validate_optional_non_empty_query_string(query.analyzer.as_deref())?;
        }
        OpenSearchQueryBuilderWire::MoreLikeThis(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            let Some(fields) = query.fields.as_ref() else {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this fields",
                    reason: "OpenSearch MoreLikeThisQueryBuilder fields are required by this execution subset",
                });
            };
            if fields.is_empty() || fields.iter().any(|field| field.is_empty()) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this fields",
                    reason: "OpenSearch MoreLikeThisQueryBuilder fields must be non-empty strings",
                });
            }
            if query.like_texts.len() != 1 || query.like_texts.iter().any(|text| text.is_empty()) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this like",
                    reason: "OpenSearch MoreLikeThisQueryBuilder requires exactly one non-empty like text in this execution subset",
                });
            }
            if !query.unlike_texts.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this unlike",
                    reason: "OpenSearch MoreLikeThisQueryBuilder unlike text is not supported by this execution subset",
                });
            }
            if query.max_query_terms <= 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this max_query_terms",
                    reason: "OpenSearch MoreLikeThisQueryBuilder max_query_terms must be positive",
                });
            }
            if query.min_term_freq < 0 || query.min_doc_freq < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this frequency",
                    reason: "OpenSearch MoreLikeThisQueryBuilder frequency thresholds must be non-negative",
                });
            }
            if query.max_doc_freq != i32::MAX
                || query.min_word_length != 0
                || query.max_word_length != 0
            {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this options",
                    reason: "OpenSearch MoreLikeThisQueryBuilder max_doc_freq and word length options must stay at OpenSearch defaults in this execution subset",
                });
            }
            if query.stop_words.is_some() || query.analyzer.is_some() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this analysis",
                    reason: "OpenSearch MoreLikeThisQueryBuilder analyzer and stop_words are not supported by this execution subset",
                });
            }
            if query.minimum_should_match != "30%" {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this minimum_should_match",
                    reason: "OpenSearch MoreLikeThisQueryBuilder minimum_should_match must stay at the OpenSearch default in this execution subset",
                });
            }
            if query.boost_terms.as_f64() != Some(0.0) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this boost_terms",
                    reason: "OpenSearch MoreLikeThisQueryBuilder boost_terms must stay at the OpenSearch default in this execution subset",
                });
            }
            if query.include || !query.fail_on_unsupported_field {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query more_like_this flags",
                    reason: "OpenSearch MoreLikeThisQueryBuilder include and fail_on_unsupported_field must stay at OpenSearch defaults in this execution subset",
                });
            }
        }
        OpenSearchQueryBuilderWire::MultiMatch(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            validate_match_query_value(&query.value)?;
            for field in &query.fields {
                if field.field_name.is_empty() {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query",
                        reason: "OpenSearch MultiMatchQueryBuilder field name must be non-empty",
                    });
                }
                if !field.boost.is_finite() || field.boost < 0.0 {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query",
                        reason: "OpenSearch MultiMatchQueryBuilder field boost must be finite and non-negative",
                    });
                }
            }
            validate_optional_non_empty_query_string(query.analyzer.as_deref())?;
            if query.slop < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MultiMatchQueryBuilder slop must be non-negative",
                });
            }
            if let Some(fuzziness) = &query.fuzziness {
                validate_fuzziness(fuzziness)?;
            }
            if query.prefix_length < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MultiMatchQueryBuilder prefix length must be non-negative",
                });
            }
            if query.max_expansions <= 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MultiMatchQueryBuilder max expansions must be positive",
                });
            }
            validate_optional_non_empty_query_string(query.minimum_should_match.as_deref())?;
            validate_optional_non_empty_query_string(query.fuzzy_rewrite.as_deref())?;
            if query.tie_breaker.is_some_and(|value| !value.is_finite()) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch MultiMatchQueryBuilder tie breaker must be finite when present",
                });
            }
            if query
                .cutoff_frequency
                .is_some_and(|value| !value.is_finite())
            {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch MultiMatchQueryBuilder cutoff frequency must be finite when present",
                });
            }
            if query.zero_terms_query == OpenSearchZeroTermsQueryWire::Null {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch MultiMatchQueryBuilder zero terms query must be NONE or ALL",
                });
            }
        }
        OpenSearchQueryBuilderWire::Nested(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.path.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch NestedQueryBuilder path must be non-empty",
                });
            }
            validate_query_builder(Some(query.query.as_ref()))?;
        }
        OpenSearchQueryBuilderWire::Prefix(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch PrefixQueryBuilder field name must be non-empty",
                });
            }
            validate_optional_non_empty_query_string(query.rewrite.as_deref())?;
        }
        OpenSearchQueryBuilderWire::QueryString(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.query_string.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch QueryStringQueryBuilder query string must be non-empty in this subset",
                });
            }
            validate_optional_non_empty_query_string(query.default_field.as_deref())?;
            for field in &query.fields {
                if field.field_name.is_empty() {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query",
                        reason: "OpenSearch QueryStringQueryBuilder field name must be non-empty",
                    });
                }
                if !field.boost.is_finite() || field.boost < 0.0 {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query",
                        reason: "OpenSearch QueryStringQueryBuilder field boost must be finite and non-negative",
                    });
                }
            }
            validate_optional_non_empty_query_string(query.analyzer.as_deref())?;
            validate_optional_non_empty_query_string(query.quote_analyzer.as_deref())?;
            validate_optional_non_empty_query_string(query.quote_field_suffix.as_deref())?;
            validate_fuzziness(&query.fuzziness)?;
            if query.fuzzy_prefix_length < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch QueryStringQueryBuilder fuzzy prefix length must be non-negative",
                });
            }
            if query.fuzzy_max_expansions <= 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch QueryStringQueryBuilder fuzzy max expansions must be positive",
                });
            }
            validate_optional_non_empty_query_string(query.fuzzy_rewrite.as_deref())?;
            if query.phrase_slop < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch QueryStringQueryBuilder phrase slop must be non-negative",
                });
            }
            if query.tie_breaker.is_some_and(|value| !value.is_finite()) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch QueryStringQueryBuilder tie breaker must be finite when present",
                });
            }
            validate_optional_non_empty_query_string(query.rewrite.as_deref())?;
            validate_optional_non_empty_query_string(query.minimum_should_match.as_deref())?;
            validate_optional_non_empty_query_string(query.time_zone.as_deref())?;
            if query.max_determinized_states < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch QueryStringQueryBuilder max determinized states must be non-negative",
                });
            }
        }
        OpenSearchQueryBuilderWire::Range(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch RangeQueryBuilder field name must be non-empty",
                });
            }
            validate_range_bound_value(&query.from)?;
            validate_range_bound_value(&query.to)?;
            validate_optional_non_empty_query_string(query.format.as_deref())?;
        }
        OpenSearchQueryBuilderWire::Regexp(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch RegexpQueryBuilder field name must be non-empty",
                });
            }
            if query.syntax_flags_value < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch RegexpQueryBuilder flags value must be non-negative",
                });
            }
            if query.max_determinized_states < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch RegexpQueryBuilder max determinized states must be non-negative",
                });
            }
            validate_optional_non_empty_query_string(query.rewrite.as_deref())?;
        }
        OpenSearchQueryBuilderWire::ScriptScore(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            validate_query_builder(Some(query.query.as_ref()))?;
            validate_inline_script(
                &query.script,
                "search request source query script_score script",
            )?;
            if query
                .script
                .source
                .parse::<f64>()
                .ok()
                .filter(|score| *score > 0.0)
                .is_none()
            {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query script_score script",
                    reason: "OpenSearch ScriptScoreQueryBuilder script source must be a positive numeric string in this execution subset",
                });
            }
            if query
                .min_score
                .is_some_and(|min_score| !min_score.is_finite() || min_score < 0.0)
            {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch ScriptScoreQueryBuilder min_score must be finite and non-negative when present",
                });
            }
        }
        OpenSearchQueryBuilderWire::SimpleQueryString(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.query_text.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch SimpleQueryStringBuilder query text must be non-empty in this subset",
                });
            }
            for field in &query.fields {
                if field.field_name.is_empty() {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query",
                        reason: "OpenSearch SimpleQueryStringBuilder field name must be non-empty",
                    });
                }
                if !field.boost.is_finite() || field.boost < 0.0 {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query",
                        reason: "OpenSearch SimpleQueryStringBuilder field boost must be finite and non-negative",
                    });
                }
            }
            if query.flags < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch SimpleQueryStringBuilder flags must be non-negative",
                });
            }
            validate_optional_non_empty_query_string(query.analyzer.as_deref())?;
            validate_optional_non_empty_query_string(query.minimum_should_match.as_deref())?;
            validate_optional_non_empty_query_string(query.quote_field_suffix.as_deref())?;
            if query.fuzzy_prefix_length < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch SimpleQueryStringBuilder fuzzy prefix length must be non-negative",
                });
            }
            if query.fuzzy_max_expansions <= 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch SimpleQueryStringBuilder fuzzy max expansions must be positive",
                });
            }
        }
        OpenSearchQueryBuilderWire::SpanMulti(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if !matches!(query.query.as_ref(), OpenSearchQueryBuilderWire::Prefix(_)) {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query span_multi match",
                    reason: "OpenSearch SpanMultiTermQueryBuilder match must be a prefix query in this execution subset",
                });
            }
            validate_query_builder(Some(query.query.as_ref()))?;
        }
        OpenSearchQueryBuilderWire::SpanNear(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.clauses.len() < 2 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch SpanNearQueryBuilder clauses must contain at least two span queries",
                });
            }
            if query.slop < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch SpanNearQueryBuilder slop must be non-negative",
                });
            }
            for clause in &query.clauses {
                if !query_builder_is_supported_span_clause(clause) {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query span_near clauses",
                        reason: "OpenSearch SpanNearQueryBuilder clauses must be span_term or span_multi(prefix) queries in this execution subset",
                    });
                }
                validate_query_builder(Some(clause))?;
            }
        }
        OpenSearchQueryBuilderWire::SpanOr(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.clauses.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch SpanOrQueryBuilder clauses must be non-empty",
                });
            }
            for clause in &query.clauses {
                if !query_builder_is_supported_span_clause(clause) {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query span_or clauses",
                        reason: "OpenSearch SpanOrQueryBuilder clauses must be span_term or span_multi(prefix) queries in this execution subset",
                    });
                }
                validate_query_builder(Some(clause))?;
            }
        }
        OpenSearchQueryBuilderWire::SpanTerm(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch SpanTermQueryBuilder field name must be non-empty",
                });
            }
            match &query.value {
                Value::String(value) if !value.is_empty() => {}
                Value::String(_) => {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query",
                        reason: "OpenSearch SpanTermQueryBuilder string value must be non-empty",
                    });
                }
                _ => {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "search request source query",
                        reason: "OpenSearch SpanTermQueryBuilder value must be a string in this execution subset",
                    });
                }
            }
        }
        OpenSearchQueryBuilderWire::Term(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch TermQueryBuilder field name must be non-empty",
                });
            }
            validate_term_query_value(&query.value)?;
        }
        OpenSearchQueryBuilderWire::Terms(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch TermsQueryBuilder field name must be non-empty",
                });
            }
            for value in &query.values {
                validate_terms_query_value(value)?;
            }
        }
        OpenSearchQueryBuilderWire::TermsSet(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch TermsSetQueryBuilder field name must be non-empty",
                });
            }
            if query.values.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason:
                        "OpenSearch TermsSetQueryBuilder values must be non-empty in this subset",
                });
            }
            for value in &query.values {
                validate_terms_query_value(value)?;
            }
            if query.minimum_should_match_field.is_some() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query terms_set minimum_should_match_field",
                    reason: "OpenSearch TermsSetQueryBuilder minimum_should_match_field requires document-field threshold execution",
                });
            }
            let Some(script) = query.minimum_should_match_script.as_ref() else {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query terms_set minimum_should_match_script",
                    reason: "OpenSearch TermsSetQueryBuilder minimum_should_match_script is required by this execution subset",
                });
            };
            validate_inline_script(
                script,
                "search request source query terms_set minimum_should_match_script",
            )?;
            if script
                .source
                .parse::<u64>()
                .ok()
                .filter(|threshold| *threshold > 0)
                .is_none()
            {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query terms_set minimum_should_match_script",
                    reason: "OpenSearch TermsSetQueryBuilder minimum_should_match_script source must be a positive integer string in this execution subset",
                });
            }
        }
        OpenSearchQueryBuilderWire::Wildcard(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.field_name.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch WildcardQueryBuilder field name must be non-empty",
                });
            }
            validate_optional_non_empty_query_string(query.rewrite.as_deref())?;
        }
        OpenSearchQueryBuilderWire::Wrapper(query) => {
            validate_query_boost_and_name(query.boost, query.query_name.as_deref())?;
            if query.source.is_empty() {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search request source query",
                    reason: "OpenSearch WrapperQueryBuilder source must be non-empty",
                });
            }
        }
    }
    Ok(())
}

fn validate_optional_non_empty_query_string(
    value: Option<&str>,
) -> Result<(), TransportActionWireError> {
    if value.is_some_and(str::is_empty) {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape: "search request source query",
            reason: "OpenSearch QueryBuilder optional strings must be non-empty when present",
        });
    }
    Ok(())
}

fn validate_match_query_value(value: &Value) -> Result<(), TransportActionWireError> {
    match value {
        Value::String(_) | Value::Bool(_) | Value::Number(_) => Ok(()),
        Value::Null => Err(TransportActionWireError::UnsupportedWireShape {
            shape: "search request source query",
            reason: "OpenSearch MatchQueryBuilder query value cannot be null",
        }),
        Value::Array(_) | Value::Object(_) => Err(TransportActionWireError::UnsupportedWireShape {
            shape: "search request source query",
            reason: "OpenSearch MatchQueryBuilder query value must be scalar",
        }),
    }
}

fn validate_fuzziness(value: &OpenSearchFuzzinessWire) -> Result<(), TransportActionWireError> {
    if value.value.is_empty() {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape: "search request source query",
            reason: "OpenSearch Fuzziness value must be non-empty",
        });
    }
    if let Some(bounds) = value.custom_auto {
        if bounds.low_distance < 0
            || bounds.high_distance < 0
            || bounds.low_distance > bounds.high_distance
        {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "search request source query",
                reason: "OpenSearch Fuzziness custom AUTO bounds must be non-negative and ordered",
            });
        }
    }
    Ok(())
}

fn write_fuzziness(output: &mut StreamOutput, value: &OpenSearchFuzzinessWire) {
    output.write_string(&value.value);
    if let Some(bounds) = value.custom_auto {
        output.write_bool(true);
        output.write_vint(bounds.low_distance);
        output.write_vint(bounds.high_distance);
    } else {
        output.write_bool(false);
    }
}

fn write_optional_fuzziness(output: &mut StreamOutput, value: Option<&OpenSearchFuzzinessWire>) {
    if let Some(value) = value {
        output.write_bool(true);
        write_fuzziness(output, value);
    } else {
        output.write_bool(false);
    }
}

fn read_fuzziness(
    input: &mut StreamInput,
) -> Result<OpenSearchFuzzinessWire, TransportActionWireError> {
    let value = input.read_string()?;
    let custom_auto = if input.read_bool()? {
        Some(OpenSearchFuzzinessAutoBoundsWire {
            low_distance: input.read_vint()?,
            high_distance: input.read_vint()?,
        })
    } else {
        None
    };
    let fuzziness = OpenSearchFuzzinessWire { value, custom_auto };
    validate_fuzziness(&fuzziness)?;
    Ok(fuzziness)
}

fn read_optional_fuzziness(
    input: &mut StreamInput,
) -> Result<Option<OpenSearchFuzzinessWire>, TransportActionWireError> {
    if input.read_bool()? {
        Ok(Some(read_fuzziness(input)?))
    } else {
        Ok(None)
    }
}

