#[derive(Clone, Debug, Eq, PartialEq)]
pub struct OpenSearchGetAllPitsRequestWire {
    pub parent_task_node: String,
    pub parent_task_id: Option<i64>,
    pub node_ids: Option<Vec<String>>,
    pub concrete_nodes: Option<Vec<OpenSearchDiscoveryNodeWire>>,
    pub timeout: Option<TimeValueWire>,
}

impl Default for OpenSearchGetAllPitsRequestWire {
    fn default() -> Self {
        Self {
            parent_task_node: String::new(),
            parent_task_id: None,
            node_ids: None,
            concrete_nodes: None,
            timeout: None,
        }
    }
}

impl OpenSearchGetAllPitsRequestWire {
    pub fn write(&self, output: &mut StreamOutput) {
        write_parent_task_id(output, &self.parent_task_node, self.parent_task_id);
        write_nullable_string_array(output, self.node_ids.as_deref());
        write_optional_discovery_node_array(output, self.concrete_nodes.as_deref());
        write_optional_time_value(output, self.timeout.as_ref());
    }

    pub fn read(bytes: Bytes) -> Result<Self, TransportActionWireError> {
        let mut input = StreamInput::new(bytes);
        let (parent_task_node, parent_task_id) = read_parent_task_id(&mut input)?;
        let node_ids = read_nullable_string_array(&mut input)?;
        let concrete_nodes = read_optional_discovery_node_array(&mut input)?;
        let request = Self {
            parent_task_node,
            parent_task_id,
            node_ids,
            concrete_nodes,
            timeout: read_optional_time_value(&mut input)?,
        };
        require_no_trailing_bytes(&input)?;
        Ok(request)
    }

    pub fn validate_supported_subset(&self) -> Result<(), TransportActionWireError> {
        if let Some(concrete_nodes) = &self.concrete_nodes {
            for node in concrete_nodes {
                node.validate_supported_subset()?;
            }
        }
        if let Some(timeout) = &self.timeout {
            if timeout.duration < -1 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "get all pits timeout",
                    reason: "OpenSearch TimeValue rejects durations below -1",
                });
            }
            if timeout.time_unit_ordinal > 6 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "get all pits timeout unit",
                    reason: "OpenSearch get-all-PITs timeout uses an unknown time unit",
                });
            }
        }
        Ok(())
    }

    pub fn supports_local_lifecycle_subset(&self) -> Result<(), TransportActionWireError> {
        self.validate_supported_subset()?;
        if self.node_ids.as_ref().is_some_and(|node_ids| {
            !node_ids
                .iter()
                .all(|node_id| node_id == "_all" || node_id == "_local")
        }) {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get all pits node filter",
                reason: "node-scoped PIT listing requires runtime node fanout semantics",
            });
        }
        if self
            .concrete_nodes
            .as_ref()
            .is_some_and(|concrete_nodes| concrete_nodes.len() > 1)
        {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get all pits concrete nodes",
                reason: "concrete-node PIT listing requires runtime node fanout semantics",
            });
        }
        Ok(())
    }

    pub fn reject_unsupported_execution(&self) -> Result<(), TransportActionWireError> {
        self.supports_local_lifecycle_subset()?;
        Err(TransportActionWireError::UnsupportedWireShape {
            shape: "get all pits execution",
            reason:
                "use supports_local_lifecycle_subset for the implemented local PIT listing adapter",
        })
    }
}

