fn write_generic_string_map(output: &mut StreamOutput, values: &BTreeMap<String, String>) {
    output.write_byte(10);
    output.write_vint(values.len() as i32);
    for (key, value) in values {
        output.write_string(key);
        output.write_byte(0);
        output.write_string(value);
    }
}

fn read_generic_string_map(
    input: &mut StreamInput,
) -> Result<BTreeMap<String, String>, TransportActionWireError> {
    let map_type = input.read_byte()?;
    if map_type != 9 && map_type != 10 {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape: "generic string map",
            reason: "only OpenSearch generic linked-hash-map/hash-map string values are decoded",
        });
    }
    let len = input.read_vint()?;
    if len < 0 {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape: "generic string map",
            reason: "generic map length cannot be negative",
        });
    }
    let mut values = BTreeMap::new();
    for _ in 0..len {
        let key = input.read_string()?;
        let value_type = input.read_byte()?;
        if value_type != 0 {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "generic string map value",
                reason: "only OpenSearch generic string map values are decoded",
            });
        }
        values.insert(key, input.read_string()?);
    }
    Ok(values)
}

fn write_optional_vlong(output: &mut StreamOutput, value: Option<i64>) {
    if let Some(value) = value {
        output.write_bool(true);
        output.write_vlong(value);
    } else {
        output.write_bool(false);
    }
}

fn read_optional_vlong(input: &mut StreamInput) -> Result<Option<i64>, TransportActionWireError> {
    if input.read_bool()? {
        Ok(Some(input.read_vlong()?))
    } else {
        Ok(None)
    }
}

fn write_empty_generic_map(output: &mut StreamOutput) {
    output.write_byte(10);
    output.write_vint(0);
}

fn read_empty_generic_map(input: &mut StreamInput) -> Result<(), TransportActionWireError> {
    let tag = input.read_byte()?;
    if tag != 10 {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape: "generic map",
            reason: "the implemented analyze token subset only decodes empty generic maps",
        });
    }
    let size = input.read_vint()?;
    if size != 0 {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape: "generic map entries",
            reason: "the implemented analyze token subset only decodes empty attributes",
        });
    }
    Ok(())
}

fn write_optional_bool(output: &mut StreamOutput, value: Option<bool>) {
    match value {
        Some(false) => output.write_byte(0),
        Some(true) => output.write_byte(1),
        None => output.write_byte(2),
    }
}

fn read_optional_bool(input: &mut StreamInput) -> Result<Option<bool>, TransportActionWireError> {
    match input.read_byte()? {
        0 => Ok(Some(false)),
        1 => Ok(Some(true)),
        2 => Ok(None),
        _ => Err(TransportActionWireError::UnsupportedWireShape {
            shape: "optional boolean",
            reason: "optional boolean must use the OpenSearch 0/1/2 wire encoding",
        }),
    }
}

fn write_optional_int(output: &mut StreamOutput, value: Option<i32>) {
    if let Some(value) = value {
        output.write_bool(true);
        output.write_i32(value);
    } else {
        output.write_bool(false);
    }
}

fn read_optional_int(input: &mut StreamInput) -> Result<Option<i32>, TransportActionWireError> {
    if input.read_bool()? {
        Ok(Some(input.read_i32()?))
    } else {
        Ok(None)
    }
}

fn write_optional_float(output: &mut StreamOutput, value: Option<f32>) {
    if let Some(value) = value {
        output.write_bool(true);
        output.write_f32(value);
    } else {
        output.write_bool(false);
    }
}

fn read_optional_float(input: &mut StreamInput) -> Result<Option<f32>, TransportActionWireError> {
    if input.read_bool()? {
        Ok(Some(input.read_f32()?))
    } else {
        Ok(None)
    }
}

fn write_optional_text_string(
    output: &mut StreamOutput,
    value: Option<&str>,
) -> Result<(), TransportActionWireError> {
    if let Some(value) = value {
        let bytes = value.as_bytes();
        let len = i32::try_from(bytes.len()).map_err(|_| {
            TransportActionWireError::UnsupportedWireShape {
                shape: "optional text",
                reason: "OpenSearch Text byte length does not fit the int wire shape",
            }
        })?;
        output.write_i32(len);
        output.write_raw_bytes(bytes);
    } else {
        output.write_i32(-1);
    }
    Ok(())
}

fn read_optional_text_string(
    input: &mut StreamInput,
) -> Result<Option<String>, TransportActionWireError> {
    let len = input.read_i32()?;
    if len == -1 {
        return Ok(None);
    }
    if len < 0 {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape: "optional text",
            reason: "OpenSearch optional Text length cannot be negative except -1",
        });
    }
    let bytes = input.read_bytes(len as usize)?;
    let value = std::str::from_utf8(&bytes).map_err(|_| {
        TransportActionWireError::UnsupportedWireShape {
            shape: "optional text",
            reason: "only UTF-8 OpenSearch Text values are decoded by this subset",
        }
    })?;
    Ok(Some(value.to_string()))
}

fn read_optional_json_bytes_reference(
    input: &mut StreamInput,
) -> Result<Option<Value>, TransportActionWireError> {
    let value = input.read_bytes_reference()?;
    if value.is_empty() {
        return Ok(None);
    }
    serde_json::from_slice(&value)
        .map(Some)
        .map_err(TransportActionWireError::JsonDecode)
}

fn normalized_sort_values(sort: Option<Value>) -> Vec<Value> {
    match sort {
        Some(Value::Array(values)) => values,
        Some(value) => vec![value],
        None => Vec::new(),
    }
}

fn normalized_document_fields(fields: Option<Value>) -> BTreeMap<String, Vec<Value>> {
    let mut normalized = BTreeMap::new();
    let Some(Value::Object(fields)) = fields else {
        return normalized;
    };
    for (name, value) in fields {
        let values = match value {
            Value::Array(values) => values,
            value => vec![value],
        };
        normalized.insert(name, values);
    }
    normalized
}

fn normalized_highlight_fields(highlight: Option<Value>) -> BTreeMap<String, Option<Vec<String>>> {
    let mut normalized = BTreeMap::new();
    let Some(Value::Object(fields)) = highlight else {
        return normalized;
    };
    for (name, value) in fields {
        let fragments = match value {
            Value::Null => None,
            Value::Array(values) => Some(
                values
                    .into_iter()
                    .map(json_value_to_highlight_fragment)
                    .collect(),
            ),
            Value::String(value) => Some(vec![value]),
            value => Some(vec![json_value_to_highlight_fragment(value)]),
        };
        normalized.insert(name, fragments);
    }
    normalized
}

fn json_value_to_highlight_fragment(value: Value) -> String {
    match value {
        Value::String(value) => value,
        value => value.to_string(),
    }
}

fn write_document_field_map(
    output: &mut StreamOutput,
    fields: &BTreeMap<String, Vec<Value>>,
) -> Result<(), TransportActionWireError> {
    output.write_vint(fields.len() as i32);
    for (name, values) in fields {
        output.write_string(name);
        write_document_field(output, name, values)?;
    }
    Ok(())
}

fn read_document_field_map(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<BTreeMap<String, Vec<Value>>, TransportActionWireError> {
    let len = read_len(input)?;
    let mut fields = BTreeMap::new();
    for _ in 0..len {
        let key = input.read_string()?;
        let (name, values) = read_document_field(input, shape)?;
        if key != name {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape,
                reason: "OpenSearch DocumentField map key must match the embedded field name",
            });
        }
        fields.insert(name, values);
    }
    Ok(fields)
}

fn write_document_field(
    output: &mut StreamOutput,
    name: &str,
    values: &[Value],
) -> Result<(), TransportActionWireError> {
    output.write_string(name);
    output.write_vint(values.len() as i32);
    for value in values {
        write_generic_json_value(output, value)?;
    }
    Ok(())
}

fn read_document_field(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<(String, Vec<Value>), TransportActionWireError> {
    let name = input.read_string()?;
    let len = read_len(input)?;
    let mut values = Vec::with_capacity(len);
    for _ in 0..len {
        values.push(read_generic_json_value(input, shape)?);
    }
    Ok((name, values))
}

fn write_highlight_field_map(
    output: &mut StreamOutput,
    fields: &BTreeMap<String, Option<Vec<String>>>,
) -> Result<(), TransportActionWireError> {
    output.write_vint(fields.len() as i32);
    for (name, fragments) in fields {
        write_highlight_field(output, name, fragments.as_deref())?;
    }
    Ok(())
}

fn read_highlight_field_map(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<BTreeMap<String, Option<Vec<String>>>, TransportActionWireError> {
    let len = read_len(input)?;
    let mut fields = BTreeMap::new();
    for _ in 0..len {
        let (name, fragments) = read_highlight_field(input, shape)?;
        fields.insert(name, fragments);
    }
    Ok(fields)
}

fn write_highlight_field(
    output: &mut StreamOutput,
    name: &str,
    fragments: Option<&[String]>,
) -> Result<(), TransportActionWireError> {
    output.write_string(name);
    if let Some(fragments) = fragments {
        output.write_bool(true);
        output.write_vint(fragments.len() as i32);
        for fragment in fragments {
            write_text_string(output, fragment)?;
        }
    } else {
        output.write_bool(false);
    }
    Ok(())
}

fn read_highlight_field(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<(String, Option<Vec<String>>), TransportActionWireError> {
    let name = input.read_string()?;
    if !input.read_bool()? {
        return Ok((name, None));
    }
    let len = read_len(input)?;
    let mut fragments = Vec::with_capacity(len);
    for _ in 0..len {
        fragments.push(read_text_string(input, shape)?);
    }
    Ok((name, Some(fragments)))
}

fn write_search_explanation(
    output: &mut StreamOutput,
    explanation: &Value,
) -> Result<(), TransportActionWireError> {
    let matches = explanation
        .get("match")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    output.write_bool(matches);
    output.write_string(
        explanation
            .get("description")
            .and_then(Value::as_str)
            .unwrap_or_default(),
    );
    let details = explanation
        .get("details")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    output.write_vint(details.len() as i32);
    for detail in details {
        write_search_explanation(output, detail)?;
    }
    if matches {
        write_explanation_number(output, explanation.get("value").unwrap_or(&Value::from(0)))?;
    }
    Ok(())
}

fn read_search_explanation(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<Value, TransportActionWireError> {
    let matches = input.read_bool()?;
    let description = input.read_string()?;
    let detail_count = read_len(input)?;
    let mut details = Vec::with_capacity(detail_count);
    for _ in 0..detail_count {
        details.push(read_search_explanation(input, shape)?);
    }
    let mut object = serde_json::Map::new();
    if !matches {
        object.insert("match".to_string(), Value::Bool(false));
    }
    object.insert("description".to_string(), Value::String(description));
    object.insert("details".to_string(), Value::Array(details));
    if matches {
        object.insert("value".to_string(), read_explanation_number(input, shape)?);
    }
    Ok(Value::Object(object))
}

fn write_explanation_number(
    output: &mut StreamOutput,
    value: &Value,
) -> Result<(), TransportActionWireError> {
    let Some(number) = value.as_number() else {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape: "search hit explanation",
            reason: "OpenSearch explanation values must be numeric",
        });
    };
    if let Some(value) = number.as_i64() {
        output.write_byte(2);
        output.write_zlong(value);
    } else if let Some(value) = number.as_u64() {
        let value =
            i64::try_from(value).map_err(|_| TransportActionWireError::UnsupportedWireShape {
                shape: "search hit explanation",
                reason: "unsigned explanation value does not fit the OpenSearch long wire shape",
            })?;
        output.write_byte(2);
        output.write_zlong(value);
    } else if let Some(value) = number.as_f64() {
        output.write_byte(1);
        output.write_f64(value);
    } else {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape: "search hit explanation",
            reason: "JSON explanation value cannot be mapped to an OpenSearch number",
        });
    }
    Ok(())
}

fn read_explanation_number(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<Value, TransportActionWireError> {
    match input.read_byte()? {
        0 => serde_json::Number::from_f64(input.read_f32()? as f64)
            .map(Value::Number)
            .ok_or(TransportActionWireError::UnsupportedWireShape {
                shape,
                reason: "OpenSearch float explanation value is not a finite JSON number",
            }),
        1 => serde_json::Number::from_f64(input.read_f64()?)
            .map(Value::Number)
            .ok_or(TransportActionWireError::UnsupportedWireShape {
                shape,
                reason: "OpenSearch double explanation value is not a finite JSON number",
            }),
        2 => Ok(Value::Number(read_zlong(input)?.into())),
        _ => Err(TransportActionWireError::UnsupportedWireShape {
            shape,
            reason: "OpenSearch explanation number type is not supported",
        }),
    }
}

fn write_text_string(
    output: &mut StreamOutput,
    value: &str,
) -> Result<(), TransportActionWireError> {
    let bytes = value.as_bytes();
    let len =
        i32::try_from(bytes.len()).map_err(|_| TransportActionWireError::UnsupportedWireShape {
            shape: "text",
            reason: "OpenSearch Text byte length does not fit the int wire shape",
        })?;
    output.write_i32(len);
    output.write_raw_bytes(bytes);
    Ok(())
}

fn read_text_string(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<String, TransportActionWireError> {
    let len = input.read_i32()?;
    if len < 0 {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape,
            reason: "OpenSearch Text length cannot be negative",
        });
    }
    let bytes = input.read_bytes(len as usize)?;
    let value = std::str::from_utf8(&bytes).map_err(|_| {
        TransportActionWireError::UnsupportedWireShape {
            shape,
            reason: "only UTF-8 OpenSearch Text values are decoded by this subset",
        }
    })?;
    Ok(value.to_string())
}

fn write_generic_json_value(
    output: &mut StreamOutput,
    value: &Value,
) -> Result<(), TransportActionWireError> {
    match value {
        Value::Null => output.write_byte(255),
        Value::String(value) => {
            output.write_byte(0);
            output.write_string(value);
        }
        Value::Number(value) => {
            if let Some(value) = value.as_i64() {
                output.write_byte(2);
                output.write_i64(value);
            } else if let Some(value) = value.as_u64() {
                let value = i64::try_from(value).map_err(|_| {
                    TransportActionWireError::UnsupportedWireShape {
                        shape: "generic json value",
                        reason: "unsigned generic JSON value does not fit the OpenSearch long wire shape",
                    }
                })?;
                output.write_byte(2);
                output.write_i64(value);
            } else if let Some(value) = value.as_f64() {
                output.write_byte(4);
                output.write_f64(value);
            } else {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "generic json value",
                    reason: "JSON number cannot be mapped to an OpenSearch generic value",
                });
            }
        }
        Value::Bool(value) => {
            output.write_byte(5);
            output.write_bool(*value);
        }
        Value::Array(values) => {
            output.write_byte(7);
            output.write_vint(values.len() as i32);
            for value in values {
                write_generic_json_value(output, value)?;
            }
        }
        Value::Object(values) => {
            output.write_byte(10);
            output.write_vint(values.len() as i32);
            for (key, value) in values {
                output.write_string(key);
                write_generic_json_value(output, value)?;
            }
        }
    }
    Ok(())
}

fn read_generic_json_value(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<Value, TransportActionWireError> {
    match input.read_byte()? {
        255 => Ok(Value::Null),
        0 => Ok(Value::String(input.read_string()?)),
        1 => Ok(Value::Number(input.read_i32()?.into())),
        2 => Ok(Value::Number(input.read_i64()?.into())),
        3 => serde_json::Number::from_f64(input.read_f32()? as f64)
            .map(Value::Number)
            .ok_or(TransportActionWireError::UnsupportedWireShape {
                shape,
                reason: "OpenSearch float generic value is not a finite JSON number",
            }),
        4 => serde_json::Number::from_f64(input.read_f64()?)
            .map(Value::Number)
            .ok_or(TransportActionWireError::UnsupportedWireShape {
                shape,
                reason: "OpenSearch double generic value is not a finite JSON number",
            }),
        5 => Ok(Value::Bool(input.read_bool()?)),
        7 | 8 => {
            let len = read_len(input)?;
            let mut values = Vec::with_capacity(len);
            for _ in 0..len {
                values.push(read_generic_json_value(input, shape)?);
            }
            Ok(Value::Array(values))
        }
        9 | 10 => {
            let len = read_len(input)?;
            let mut values = serde_json::Map::new();
            for _ in 0..len {
                let key = input.read_string()?;
                values.insert(key, read_generic_json_value(input, shape)?);
            }
            Ok(Value::Object(values))
        }
        11 => Ok(Value::Number(i64::from(input.read_byte()? as i8).into())),
        16 => Ok(Value::Number(i64::from(input.read_i16()?).into())),
        _ => Err(TransportActionWireError::UnsupportedWireShape {
            shape,
            reason: "OpenSearch generic value type is not decoded by this SearchHit fields subset",
        }),
    }
}

fn write_search_sort_values(
    output: &mut StreamOutput,
    values: &[Value],
) -> Result<(), TransportActionWireError> {
    output.write_vint(values.len() as i32);
    for value in values {
        write_search_sort_value(output, value)?;
    }
    Ok(())
}

fn read_search_sort_values(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<Vec<Value>, TransportActionWireError> {
    let len = read_len(input)?;
    let mut values = Vec::with_capacity(len);
    for _ in 0..len {
        values.push(read_search_sort_value(input, shape)?);
    }
    Ok(values)
}

fn write_optional_search_sort_values(
    output: &mut StreamOutput,
    values: Option<&[Value]>,
) -> Result<(), TransportActionWireError> {
    if let Some(values) = values {
        output.write_bool(true);
        write_search_sort_values(output, values)?;
    } else {
        output.write_bool(false);
    }
    Ok(())
}

fn read_optional_search_sort_values(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<Option<Vec<Value>>, TransportActionWireError> {
    if input.read_bool()? {
        Ok(Some(read_search_sort_values(input, shape)?))
    } else {
        Ok(None)
    }
}

fn validate_search_hits_collapse_tail(
    collapse_field: Option<&str>,
    collapse_values: Option<&[Value]>,
    shape: &'static str,
) -> Result<(), TransportActionWireError> {
    if collapse_field.is_some_and(str::is_empty) {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape,
            reason: "OpenSearch SearchHits collapse field must be non-empty when present",
        });
    }
    if collapse_values.is_some() && collapse_field.is_none() {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape,
            reason: "OpenSearch SearchHits collapse values require a collapse field",
        });
    }
    Ok(())
}

fn write_matched_queries(
    output: &mut StreamOutput,
    queries: &BTreeMap<String, f32>,
    version: Version,
) -> Result<(), TransportActionWireError> {
    output.write_vint(queries.len() as i32);
    if queries.is_empty() {
        return Ok(());
    }
    if version.on_or_after(OPENSEARCH_2_13_0) {
        output.write_vint(queries.len() as i32);
        for (name, score) in queries {
            output.write_string(name);
            output.write_f32(*score);
        }
    } else {
        for name in queries.keys() {
            output.write_string(name);
        }
    }
    Ok(())
}

fn read_matched_queries(
    input: &mut StreamInput,
    version: Version,
    shape: &'static str,
) -> Result<BTreeMap<String, f32>, TransportActionWireError> {
    let expected_len = read_len(input)?;
    let mut queries = BTreeMap::new();
    if expected_len == 0 {
        return Ok(queries);
    }
    if !version.on_or_after(OPENSEARCH_2_13_0) {
        for _ in 0..expected_len {
            queries.insert(input.read_string()?, f32::NAN);
        }
        return Ok(queries);
    }
    let map_len = read_len(input)?;
    if map_len != expected_len {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape,
            reason: "OpenSearch 2.13+ matched query count must match the following map size",
        });
    }
    for _ in 0..map_len {
        let name = input.read_string()?;
        let score = input.read_f32()?;
        queries.insert(name, score);
    }
    Ok(queries)
}

fn write_optional_search_shard_target(
    output: &mut StreamOutput,
    target: Option<&OpenSearchSearchShardTargetWire>,
) -> Result<(), TransportActionWireError> {
    if let Some(target) = target {
        target.validate_supported_subset()?;
        output.write_bool(true);
        write_search_shard_target(output, target)?;
    } else {
        output.write_bool(false);
    }
    Ok(())
}

fn read_optional_search_shard_target(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<Option<OpenSearchSearchShardTargetWire>, TransportActionWireError> {
    if !input.read_bool()? {
        return Ok(None);
    }
    let target = read_search_shard_target(input, shape)?;
    target.validate_supported_subset()?;
    Ok(Some(target))
}

fn write_search_shard_target(
    output: &mut StreamOutput,
    target: &OpenSearchSearchShardTargetWire,
) -> Result<(), TransportActionWireError> {
    if let Some(node_id) = target.node_id.as_deref() {
        output.write_bool(true);
        write_text_string(output, node_id)?;
    } else {
        output.write_bool(false);
    }
    output.write_string(&target.index);
    output.write_string(&target.index_uuid);
    output.write_vint(target.shard_id);
    output.write_optional_string(target.cluster_alias.as_deref());
    Ok(())
}

fn read_search_shard_target(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<OpenSearchSearchShardTargetWire, TransportActionWireError> {
    let node_id = if input.read_bool()? {
        Some(read_text_string(input, shape)?)
    } else {
        None
    };
    let index = input.read_string()?;
    let index_uuid = input.read_string()?;
    let shard_id = input.read_vint()?;
    let cluster_alias = input.read_optional_string()?;
    Ok(OpenSearchSearchShardTargetWire {
        node_id,
        index,
        index_uuid,
        shard_id,
        cluster_alias,
    })
}

fn write_search_sort_value(
    output: &mut StreamOutput,
    value: &Value,
) -> Result<(), TransportActionWireError> {
    match value {
        Value::Null => output.write_byte(0),
        Value::String(value) => {
            output.write_byte(1);
            output.write_string(value);
        }
        Value::Number(value) => {
            if let Some(value) = value.as_i64() {
                output.write_byte(3);
                output.write_i64(value);
            } else if let Some(value) = value.as_u64() {
                let value = i64::try_from(value).map_err(|_| {
                    TransportActionWireError::UnsupportedWireShape {
                        shape: "search hit sort value",
                        reason: "unsigned sort value does not fit the OpenSearch long wire shape",
                    }
                })?;
                output.write_byte(3);
                output.write_i64(value);
            } else if let Some(value) = value.as_f64() {
                output.write_byte(5);
                output.write_f64(value);
            } else {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "search hit sort value",
                    reason: "JSON number cannot be mapped to an OpenSearch sort value",
                });
            }
        }
        Value::Bool(value) => {
            output.write_byte(8);
            output.write_bool(*value);
        }
        Value::Array(_) | Value::Object(_) => {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "search hit sort value",
                reason: "OpenSearch sort values must be scalar JSON values",
            });
        }
    }
    Ok(())
}

fn read_search_sort_value(
    input: &mut StreamInput,
    shape: &'static str,
) -> Result<Value, TransportActionWireError> {
    match input.read_byte()? {
        0 => Ok(Value::Null),
        1 => Ok(Value::String(input.read_string()?)),
        2 => Ok(Value::Number(input.read_i32()?.into())),
        3 => Ok(Value::Number(input.read_i64()?.into())),
        4 => serde_json::Number::from_f64(input.read_f32()? as f64)
            .map(Value::Number)
            .ok_or(TransportActionWireError::UnsupportedWireShape {
                shape,
                reason: "OpenSearch float sort value is not a finite JSON number",
            }),
        5 => serde_json::Number::from_f64(input.read_f64()?)
            .map(Value::Number)
            .ok_or(TransportActionWireError::UnsupportedWireShape {
                shape,
                reason: "OpenSearch double sort value is not a finite JSON number",
            }),
        6 => Ok(Value::Number(i64::from(input.read_byte()? as i8).into())),
        7 => Ok(Value::Number(i64::from(input.read_i16()?).into())),
        8 => Ok(Value::Bool(input.read_bool()?)),
        _ => Err(TransportActionWireError::UnsupportedWireShape {
            shape,
            reason: "OpenSearch sort value type is not decoded by this subset",
        }),
    }
}

fn build_extension_transport_message_bytes(action: &str, request_bytes: &[u8]) -> Bytes {
    let mut output = StreamOutput::new();
    output.write_byte(0x0a);
    write_protobuf_bytes(&mut output, action.as_bytes());
    output.write_byte(0x12);
    write_protobuf_bytes(&mut output, request_bytes);
    output.freeze()
}

fn write_protobuf_bytes(output: &mut StreamOutput, bytes: &[u8]) {
    output.write_vint(bytes.len() as i32);
    for byte in bytes {
        output.write_byte(*byte);
    }
}

