    #[test]
    fn opensearch_search_response_wire_round_trips_empty_hits_subset() {
        let response = OpenSearchSearchResponseWire {
            total_hits: Some(7),
            total_hits_relation: 0,
            max_score: f32::NAN,
            hits: Vec::new(),
            sort_fields: None,
            collapse_field: None,
            collapse_values: None,
            aggregations_empty: true,
            suggest_empty: true,
            timed_out: true,
            terminated_early: Some(false),
            profile_results_empty: true,
            search_ext_builders: vec![
                OpenSearchGenericSearchExtBuilderWire::new(json!("simple")),
                OpenSearchGenericSearchExtBuilderWire::new(json!({
                    "tenant": "a",
                    "enabled": true,
                    "rank": 7
                })),
                OpenSearchGenericSearchExtBuilderWire::new(json!(["first", 2, false, null])),
            ],
            processor_results: vec![OpenSearchProcessorExecutionDetailWire {
                processor_name: "filter_query".to_string(),
                duration_millis: 7,
                input_data: json!({ "query": "before" }),
                output_data: json!({ "query": "after" }),
                status: OpenSearchProcessorExecutionDetailWire::SUCCESS,
                error_message: String::new(),
                tag: "request".to_string(),
            }],
            total_shards: 3,
            successful_shards: 2,
            shard_failures: vec![OpenSearchShardSearchFailureWire {
                shard_target: Some(OpenSearchSearchShardTargetWire {
                    node_id: Some("node-b".to_string()),
                    index: "logs-000001".to_string(),
                    index_uuid: "_na_".to_string(),
                    shard_id: 1,
                    cluster_alias: None,
                }),
                reason: "bad query".to_string(),
                status: "BAD_REQUEST".to_string(),
                cause: Some(TransportError {
                    class_name: "java.lang.IllegalArgumentException".to_string(),
                    message: Some("bad query".to_string()),
                    cause: None,
                    search_context_id: None,
                }),
            }],
            skipped_shards: 0,
            scroll_id: Some("scroll-context".to_string()),
            took_millis: 12,
            phase_took: BTreeMap::from([("query".to_string(), 4), ("fetch".to_string(), 2)]),
            point_in_time_id: Some("pit-context".to_string()),
        };
        let mut output = StreamOutput::new();
        response
            .write(&mut output, OPENSEARCH_3_7_0_TRANSPORT)
            .unwrap();

        let decoded =
            OpenSearchSearchResponseWire::read(output.freeze(), OPENSEARCH_3_7_0_TRANSPORT)
                .unwrap();
        assert_eq!(decoded.total_hits, response.total_hits);
        assert_eq!(decoded.total_hits_relation, response.total_hits_relation);
        assert!(decoded.max_score.is_nan());
        assert!(decoded.aggregations_empty);
        assert!(decoded.suggest_empty);
        assert_eq!(decoded.timed_out, response.timed_out);
        assert_eq!(decoded.terminated_early, response.terminated_early);
        assert!(decoded.profile_results_empty);
        assert_eq!(decoded.search_ext_builders, response.search_ext_builders);
        assert_eq!(decoded.processor_results, response.processor_results);
        assert_eq!(decoded.total_shards, response.total_shards);
        assert_eq!(decoded.successful_shards, response.successful_shards);
        assert_eq!(decoded.shard_failures, response.shard_failures);
        assert_eq!(decoded.skipped_shards, response.skipped_shards);
        assert_eq!(decoded.scroll_id, response.scroll_id);
        assert_eq!(decoded.took_millis, response.took_millis);
        assert_eq!(decoded.phase_took, response.phase_took);
        assert_eq!(decoded.point_in_time_id, response.point_in_time_id);
        decoded.validate_supported_subset().unwrap();
    }

