    #[test]
    fn opensearch_create_pit_request_rejects_unsupported_shapes() {
        let below_time_value_floor = OpenSearchCreatePitRequestWire {
            keep_alive: TimeValueWire {
                duration: -2,
                time_unit_ordinal: TIME_UNIT_MILLISECONDS,
            },
            ..OpenSearchCreatePitRequestWire::default()
        };
        assert!(matches!(
            below_time_value_floor.reject_unsupported_execution(),
            Err(TransportActionWireError::UnsupportedWireShape {
                shape: "create pit keep alive",
                ..
            })
        ));

        let unknown_keep_alive_unit = OpenSearchCreatePitRequestWire {
            keep_alive: TimeValueWire {
                duration: 1,
                time_unit_ordinal: 7,
            },
            ..OpenSearchCreatePitRequestWire::default()
        };
        assert!(matches!(
            unknown_keep_alive_unit.reject_unsupported_execution(),
            Err(TransportActionWireError::UnsupportedWireShape {
                shape: "create pit keep alive unit",
                ..
            })
        ));

        let zero_keep_alive = OpenSearchCreatePitRequestWire {
            keep_alive: TimeValueWire {
                duration: 0,
                time_unit_ordinal: TIME_UNIT_MILLISECONDS,
            },
            ..OpenSearchCreatePitRequestWire::default()
        };
        zero_keep_alive.validate_supported_subset().unwrap();

        let minus_one_keep_alive = OpenSearchCreatePitRequestWire {
            keep_alive: TimeValueWire {
                duration: -1,
                time_unit_ordinal: TIME_UNIT_MILLISECONDS,
            },
            ..OpenSearchCreatePitRequestWire::default()
        };
        minus_one_keep_alive.validate_supported_subset().unwrap();

        let index_filter = OpenSearchCreatePitRequestWire {
            indices: vec!["logs".to_string()],
            ..OpenSearchCreatePitRequestWire::default()
        };
        index_filter.validate_supported_subset().unwrap();

        let routing = OpenSearchCreatePitRequestWire {
            routing: Some("tenant-a".to_string()),
            ..OpenSearchCreatePitRequestWire::default()
        };
        routing.validate_supported_subset().unwrap();

        let custom_indices_options = OpenSearchCreatePitRequestWire {
            indices_options: OpenSearchIndicesOptionsWire::strict_expand_hidden(),
            ..OpenSearchCreatePitRequestWire::default()
        };
        custom_indices_options.validate_supported_subset().unwrap();

        let preference = OpenSearchCreatePitRequestWire {
            preference: Some("_local".to_string()),
            ..OpenSearchCreatePitRequestWire::default()
        };
        preference.validate_supported_subset().unwrap();

        let partial_creation_enabled = OpenSearchCreatePitRequestWire {
            allow_partial_pit_creation: Some(true),
            ..OpenSearchCreatePitRequestWire::default()
        };
        partial_creation_enabled
            .validate_supported_subset()
            .unwrap();

        let partial_creation_disabled = OpenSearchCreatePitRequestWire {
            allow_partial_pit_creation: Some(false),
            ..OpenSearchCreatePitRequestWire::default()
        };
        partial_creation_disabled
            .validate_supported_subset()
            .unwrap();

        let partial_creation_missing = OpenSearchCreatePitRequestWire {
            allow_partial_pit_creation: None,
            ..OpenSearchCreatePitRequestWire::default()
        };
        partial_creation_missing
            .validate_supported_subset()
            .unwrap();
        assert!(matches!(
            partial_creation_missing.reject_unsupported_execution(),
            Err(TransportActionWireError::UnsupportedWireShape {
                shape: "create pit execution",
                ..
            })
        ));
    }

