    #[test]
    fn opensearch_get_all_pits_request_rejects_unsupported_shapes() {
        let node_filter = OpenSearchGetAllPitsRequestWire {
            node_ids: Some(vec!["node-a".to_string()]),
            ..OpenSearchGetAllPitsRequestWire::default()
        };
        node_filter.validate_supported_subset().unwrap();
        assert!(matches!(
            node_filter.reject_unsupported_execution(),
            Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get all pits node filter",
                ..
            })
        ));

        let unscoped_node_filter = OpenSearchGetAllPitsRequestWire {
            node_ids: Some(vec!["_all".to_string(), "_local".to_string()]),
            ..OpenSearchGetAllPitsRequestWire::default()
        };
        unscoped_node_filter.validate_supported_subset().unwrap();
        unscoped_node_filter
            .supports_local_lifecycle_subset()
            .unwrap();

        let timeout = OpenSearchGetAllPitsRequestWire {
            timeout: Some(TimeValueWire::seconds(30)),
            ..OpenSearchGetAllPitsRequestWire::default()
        };
        timeout.validate_supported_subset().unwrap();
        timeout.supports_local_lifecycle_subset().unwrap();
        assert!(matches!(
            timeout.reject_unsupported_execution(),
            Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get all pits execution",
                ..
            })
        ));

        let invalid_timeout = OpenSearchGetAllPitsRequestWire {
            timeout: Some(TimeValueWire {
                duration: -2,
                time_unit_ordinal: TIME_UNIT_MILLISECONDS,
            }),
            ..OpenSearchGetAllPitsRequestWire::default()
        };
        assert!(matches!(
            invalid_timeout.validate_supported_subset(),
            Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get all pits timeout",
                ..
            })
        ));

        let unknown_timeout_unit = OpenSearchGetAllPitsRequestWire {
            timeout: Some(TimeValueWire {
                duration: 1,
                time_unit_ordinal: 7,
            }),
            ..OpenSearchGetAllPitsRequestWire::default()
        };
        assert!(matches!(
            unknown_timeout_unit.validate_supported_subset(),
            Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get all pits timeout unit",
                ..
            })
        ));

        let concrete_node = OpenSearchGetAllPitsRequestWire {
            concrete_nodes: Some(vec![test_discovery_node_wire()]),
            ..OpenSearchGetAllPitsRequestWire::default()
        };
        let mut output = StreamOutput::new();
        concrete_node.write(&mut output);
        let decoded = OpenSearchGetAllPitsRequestWire::read(output.freeze()).unwrap();
        assert_eq!(decoded, concrete_node);
        decoded.validate_supported_subset().unwrap();
        decoded.supports_local_lifecycle_subset().unwrap();

        let concrete_node_fanout = OpenSearchGetAllPitsRequestWire {
            concrete_nodes: Some(vec![test_discovery_node_wire(), test_discovery_node_wire()]),
            ..OpenSearchGetAllPitsRequestWire::default()
        };
        assert!(matches!(
            concrete_node_fanout.supports_local_lifecycle_subset(),
            Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get all pits concrete nodes",
                ..
            })
        ));
    }

